INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1001, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", "春咲 ひより", 1, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 0, "お！\nあそこに困ってそうな人発見！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1002, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", "草野 優衣", 1, 0, "みんなみたいに\nわたしも強くならなきゃ", 1, 0, "大切な人を\n守れるようになりたい…って", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1003, 1, "少しは磨かれると思いますよ。", "士条 怜", 1, 0, "フェンシングを始めてみては？", 1, 0, "キミに必要な集中力と感性が", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1004, 1, "みそぎはねぇ、\nかくれんぼやりたい！", "穂高 みそぎ", 1, 0, "ねぇ、にいちゃん！", 1, 0, "今日はなにして遊ぶ？", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1006, 1, "私といっしょに…\nいかない？", "風宮 あかり", 1, 0, "風宮あかりです", 1, 0, "ねぇ…", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1007, 1, "食べ物の恨みは怖いのー", "出雲 宮子", 1, 0, "出雲宮子なのー", 1, 0, "プリンたべたいのー", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1008, 1, "いいよ。\n見られることは運命さ…", "虹村 雪", 1, 0, "ボクは虹村雪。", 1, 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1009, 1, "人呼んで「疾風の冥姫」!!", "柊杏奈", 1, 0, "フッ…聞いて後悔するがいい！", 1, 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1010, 1, "ほんまおおきにやわ～♪", "姫宮 真歩", 1, 0, "マホマホ王国のプリンセス、\nまほ姫どす", 1, 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1011, 1, "ここで会ったが\n100年目～！", "衣之咲 璃乃", 1, 0, "衣之咲璃乃です！", 1, 0, "生き別れたお兄ちゃんを探して\n三千世界！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1012, 1, "…って、お願い！\n誰にも言わないでおいて～！", "柏崎 初音", 1, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 0, "ち、超能力って…\n何のことかな～？", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1016, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", "美波 鈴奈", 1, 0, "ちょす！\n美波鈴奈だよ～♪", 1, 0, "一応カリスマ読モJKやってまっす！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1017, 1, "でも、沖縄もとってもいいとこさー", "喜屋武 香織", 1, 0, "はいたーい。\n喜屋武香織さー。", 1, 0, "東京は遊園地みたいなところさー", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1018, 1, "イオちゃんって呼んでね。", "支倉 伊緒", 1, 0, "支倉伊緒です。", 1, 0, "先生って呼ばれるのは\nくすぐったいから", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1020, 1, "ミミをおいてかないでぇ～", "茜 ミミ", 1, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 0, "あ！/\お兄ちゃ～ん\nまってよ～", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1021, 1, "ふぇぇぇぇぇん……", "栗林 くるみ", 1, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 0, "あの……\nふぇ……", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1022, 1, "なんてありがとうございます！", "風宮 より", 1, 0, "風宮よりです。\nあああああ！", 1, 0, "こんな私に貴重な時間を\n割いていただき、", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1023, 1, "私こっち行きたいー\nね、早く早くー", "北条 綾音", 1, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 0, "おにいちゃんどこいくの？\nえ？", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1025, 1, "これて何か違う…\nあああすみません！", "天野 すずめ", 1, 0, "わっ…わっ…私、\n天野すずめといいます！", 1, 0, "ふ、不束者ですが\nどうぞ末永く…って、", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1027, 1, "離しませんわ………\n絶対に…!!", "倉石 恵理子", 1, 0, "……クスクス…私は\n…倉石恵理子……", 1, 0, "あなたは…運命の……\n伴侶……", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1028, 1, "…そうでしょ？？", "佐々木 咲恋", 1, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1029, 1, "あはは、\n私もまだまだだなぁ～", "桜井 望", 1, 0, "桜井望だよ！\nよろしくねっ", 1, 0, "ぇっと…\nキミ、私のこと知らないの?!", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1030, 1, "ショーグン、\nワタシと一緒に天下統一デース！", "ニノン・ジュベール", 1, 0, "デケデケデンっ！", 1, 0, "初めまして、\n私はニノン・ジュベール申すデス！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1031, 1, "おかしいですね……", "上喜 しのぶ", 1, 0, "上喜しのぶです。\n手元のドクロが父です。", 1, 0, "でもって私の隣にいるのが……\nえ、見えない？", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1033, 1, "そう、\nオラのボケに突っ込める相方が…！", "野戸まひる", 1, 0, "目指すはビッグな\nお笑い芸人だっぺ！", 1, 0, "けんども\nそれには足りないモンが…", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1034, 1, "ちょ\nちょっと一杯飲んできます…！", "綾瀬 ゆかり", 1, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 0, "ちょっと緊張しちゃって…", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1036, 1, "これ以上お話しすることは…\nないです！", "氷川 鏡華", 1, 0, "氷川鏡華…です", 1, 0, "知らない人とは話しちゃいけないので", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1038, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", "柏崎 栞", 1, 0, "柏崎…栞です。", 1, 0, "……あ、アラーム。", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1040, 1, "野に咲く花が、\n唯一の話相手です。", "双葉 碧", 1, 0, "ふ、双葉碧です。", 1, 0, "私、一人も友達がいなくて……", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1042, 1, "そう思っています。", "三角 千歌", 1, 0, "三角千歌です。", 1, 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1043, 1, "う、疑ってすまなかったな…", "安芸 真琴", 1, 0, "安芸真琴だ。", 1, 0, "あぁ？\nお前のそいつの仲間か？", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1044, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", "イリヤ・オーンスタイン", 1, 0, "わらわこそは夜を総べる者！", 1, 0, "生けとし生ける全ての者よ！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1045, 1, "ｌク、クウカに何かご用ですか!?", "遠見 空花", 1, 0, "そこで騎士は妖精を乱暴に……", 1, 0, "ぐふふふふ……はっ！", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1046, 1, "う～ん…\n猫ってホントに最高にゃ～♪", "宮坂たまき", 1, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1048, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", "大神 美冬", 1, 0, "大神美冬よ！", 1, 0, "それでは早速クエストに…", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1049, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", "星野静流", 1, 0, "星野静流だよ！", 1, 0, "クエストもバトルも\n掃除も洗濯も", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1050, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", "玉泉美咲", 1, 0, "アタシは玉泉美咲。", 1, 0, "見ての通りの\nセクシー美少女で", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1052, 1, "？？？？", "リマ", 1, 0, "？？？", 1, 0, "？？？？", 1.4, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1053, 1, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィント", 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1058, 1, "そ、そこまでいうなら\nもらってやる", "ペコリーヌ", 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1059, 1, "そ、そこまでいうなら\nもらってやる", "コッコロ", 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, 0, 0, 2, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (1060, 1, "そ、そこまでいうなら\nもらってやる", "キャル", 1, 0, "モニカ・ヴァイスヴィントだ。", 1, 0, "菓子でつろうなどと\n稚拙な策を……", 1.5, 0, 0, 2, 0);
